# ============================ SELF-CHECK ============================
CHAPTERS_REQUIRED = {
    "أ. أجهزة تعليمية": 10,
    "ب. أنشطة تربوية": 12,
    "ج. أهمية التعليم": 8,
    "د. التربية": 9,
    "هـ. مفهوم التعليم": 10,
}


def _fail(errors):
    print("SELF-CHECK FAILED —", len(errors), "أخطاء:")
    for e in errors[:40]:
        print(" -", e)
    if len(errors) > 40:
        print(" ... وأخطاء أخرى:", len(errors) - 40)
    raise SystemExit(1)


def self_check():
    errors = []
    # 1) العدادات
    if len(NEW_CONCEPTS) != 49:
        errors.append(f"عدد المفاهيم {len(NEW_CONCEPTS)} ≠ 49")
    if len(QUESTIONS) != 98:
        errors.append(f"عدد الأسئلة {len(QUESTIONS)} ≠ 98")
    # 2) المفاهيم: cid فريد ومتسلسل، course=G1، أسماء الفصول حرفية بعددها
    cids = [c["cid"] for c in NEW_CONCEPTS]
    if len(set(cids)) != len(cids):
        errors.append("cid مكرر في المفاهيم")
    if set(cids) != {f"WE-{i:02d}" for i in range(1, 50)}:
        errors.append("تسلسل cid غير سليم (المطلوب WE-01..WE-49)")
    if any(c["course"] != "G1" for c in NEW_CONCEPTS):
        errors.append("course ليس G1 في كل المفاهيم")
    names = [c["name"] for c in NEW_CONCEPTS]
    if len(set(names)) != len(names):
        errors.append("اسم مفهوم مكرر")
    ch_counts = {}
    for c in NEW_CONCEPTS:
        ch_counts[c["chapter"]] = ch_counts.get(c["chapter"], 0) + 1
    if ch_counts != CHAPTERS_REQUIRED:
        errors.append(f"أسماء/عدد الفصول غير مطابقة حرفياً: {ch_counts}")
    cmap = {c["cid"]: c for c in NEW_CONCEPTS}
    # 3) أطوال دنيا وعدد جمل الشرح
    for c in NEW_CONCEPTS:
        if len(c.get("explanation", "")) < 120:
            errors.append(f"explanation أقصر من 120: {c['cid']}")
        sents = [s for s in re.split(r"[.؟!]\s*", c.get("explanation", "")) if s.strip()]
        if not (3 <= len(sents) <= 4):
            errors.append(f"explanation عدد الجمل {len(sents)} خارج 3-4: {c['cid']}")
        if len(c.get("example", "")) < 100:
            errors.append(f"example أقصر من 100: {c['cid']}")
    if len({c["explanation"] for c in NEW_CONCEPTS}) != len(NEW_CONCEPTS):
        errors.append("explanation مكرر")
    if len({c["example"] for c in NEW_CONCEPTS}) != len(NEW_CONCEPTS):
        errors.append("example مكرر")
    # 4) الأسئلة
    qtexts = [q["question"] for q in QUESTIONS]
    if len(set(qtexts)) != len(qtexts):
        dups = {t for t in qtexts if qtexts.count(t) > 1}
        errors.append(f"نص سؤال مكرر ({len(dups)}): {list(dups)[:2]}")
    per = {}
    for q in QUESTIONS:
        per.setdefault(q["cid"], []).append(q)
        if q["cid"] not in cmap:
            errors.append(f"سؤال لمفهوم غير موجود: {q['cid']}")
        if len(q.get("reason", "")) < 150:
            errors.append(f"reason أقصر من 150 ({len(q.get('reason', ''))}): {q['cid']}/{q['qtype']}")
        if q["diff"] not in ("سهل", "متوسط", "صعب"):
            errors.append(f"diff غير صالح: {q['cid']}/{q['qtype']}")
        if q["qtype"] == "mcq":
            opts = [q["a"], q["b"], q["c"], q["d"]]
            if len(set(opts)) != 4:
                errors.append(f"mcq خيارات غير رباعية مميزة: {q['cid']}")
            if q["correct"] not in opts:
                errors.append(f"correct ليس ضمن الخيارات: {q['cid']}")
        elif q["qtype"] == "tf":
            if q.get("a") != "صح" or q.get("b") != "خطأ":
                errors.append(f"tf خيارات غير موحدة (صح/خطأ): {q['cid']}")
            if q["correct"] not in ("صح", "خطأ"):
                errors.append(f"tf correct غير صالح: {q['cid']}")
        else:
            errors.append(f"qtype غير صالح: {q['cid']}/{q.get('qtype')}")
    for cid in cmap:
        qs = per.get(cid, [])
        if len(qs) != 2 or sorted(q["qtype"] for q in qs) != ["mcq", "tf"]:
            errors.append(f"لكل مفهوم mcq+tf بالضبط — مخالفة: {cid}")
    # 5) لا حروف لاتينية داخل الكلمات (اختصارات بين مسافات مسموحة)
    arab = "\u0600-\u06FF"
    for it, blobs in ([(c, [" ".join((c[k] for k in ("name", "explanation", "example") if c.get(k)))]) for c in NEW_CONCEPTS]
                      + [(q, [" ".join(str(q[k]) for k in ("question", "a", "b", "c", "d", "correct", "reason") if q.get(k))]) for q in QUESTIONS]):
        for blob in blobs:
            if re.search(f"[{arab}][A-Za-z]|[A-Za-z][{arab}]", blob):
                errors.append(f"حرف لاتيني ملتصق بكلمة عربية: {it.get('cid', '?')}")
            for m in re.finditer(r"[A-Za-z]+", blob):
                if not re.fullmatch(r"[A-Z]{2,4}", m.group(0)):
                    errors.append(f"رمز لاتيني غير مسموح: {m.group(0)} في {it.get('cid', '?')}")
    # 6) توزيع الصعوبة
    diffs = {"سهل": 0, "متوسط": 0, "صعب": 0}
    for q in QUESTIONS:
        diffs[q["diff"]] += 1
    if diffs != {"سهل": 25, "متوسط": 54, "صعب": 19}:
        errors.append(f"توزيع الصعوبة غير مطابق (المطلوب 25/54/19): {diffs}")
    # 7) توازن صح/خطأ تقريباً نصف/نصف
    sahih = sum(1 for q in QUESTIONS if q["qtype"] == "tf" and q["correct"] == "صح")
    if not (18 <= sahih <= 31):
        errors.append(f"tf غير متوازن: صح={sahih} من 49")
    if errors:
        _fail(errors)
    print("SELF-CHECK OK — 49 مفهوماً / 98 سؤالاً (mcq+tf لكل مفهوم)")
    print(f"الصعوبة: سهل={diffs['سهل']} متوسط={diffs['متوسط']} صعب={diffs['صعب']} | tf: صح={sahih} خطأ={49 - sahih}")
    print("الفصول:", " / ".join(f"{k}: {v}" for k, v in ch_counts.items()))


self_check()
